package com.dinkolami.dinnote;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;import android.text.*;import android.content.*;import java.util.*;
public class MainActivity extends Activity {
 LinearLayout root,items; EditText editor; String selected=null; android.content.SharedPreferences prefs;
 int green=Color.rgb(17,105,84), gold=Color.rgb(169,132,58);
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(12,76,63));getWindow().setNavigationBarColor(Color.BLACK);prefs=getSharedPreferences("notes",0);home();}
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(green);t.setPadding(24,20,24,20);return t;}
 void base(String title){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(Color.rgb(250,251,248));setContentView(root);TextView h=text(title,24);h.setBackgroundColor(Color.rgb(232,244,239));root.addView(h);}
 void home(){editor=null;selected=null;base("✦ DinNote");Button add=new Button(this);add.setText("+ Nota baharu");add.setTextColor(Color.WHITE);add.setBackgroundTintList(android.content.res.ColorStateList.valueOf(green));root.addView(add);add.setOnClickListener(v->edit(null));EditText search=new EditText(this);search.setSingleLine(true);search.setHint("Cari nota");search.setPadding(24,16,24,16);root.addView(search);ScrollView sc=new ScrollView(this);items=new LinearLayout(this);items.setOrientation(1);sc.addView(items);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){list(s.toString());}public void afterTextChanged(Editable e){}});list("");}
 void list(String filter){items.removeAllViews();ArrayList<String> keys=new ArrayList<>();for(String k:prefs.getAll().keySet())if(k.startsWith("n_"))keys.add(k);Collections.sort(keys,Collections.reverseOrder());for(String k:keys){String v=prefs.getString(k,"");if(!v.toLowerCase().contains(filter.toLowerCase()))continue;TextView t=text(v.length()>90?v.substring(0,90)+"…":v,17);t.setBackgroundColor(Color.WHITE);t.setPadding(28,24,28,24);items.addView(t);View line=new View(this);line.setBackgroundColor(0xffe5e9e5);items.addView(line,new LinearLayout.LayoutParams(-1,1));t.setOnClickListener(w->edit(k));}}
 void edit(String key){editor=null;selected=key;base("‹  DinNote · Editor");LinearLayout bar=new LinearLayout(this);Button back=new Button(this);back.setText("← Kembali");bar.addView(back);back.setOnClickListener(v->{save();home();});Button del=new Button(this);del.setText("Padam");bar.addView(del);del.setOnClickListener(v->new AlertDialog.Builder(this).setMessage("Padam nota ini?").setPositiveButton("Padam",(d,w)->{if(selected!=null)prefs.edit().remove(selected).apply();selected=null;home();}).setNegativeButton("Batal",null).show());root.addView(bar);editor=new EditText(this);editor.setGravity(Gravity.TOP);editor.setTextSize(16);editor.setPadding(28,24,28,24);editor.setHint("Tulis nota di sini…");editor.setBackgroundColor(Color.WHITE);root.addView(editor,new LinearLayout.LayoutParams(-1,0,1));if(key!=null)editor.setText(prefs.getString(key,""));editor.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){save();}public void afterTextChanged(Editable e){}});}
 void save(){if(editor==null||selected==null&&editor.getText().toString().trim().isEmpty())return;String value=editor.getText().toString();if(selected==null)selected="n_"+System.currentTimeMillis();prefs.edit().putString(selected,value).apply();}
 public void onBackPressed(){if(editor!=null){save();editor=null;home();}else super.onBackPressed();}
}
